const test = require('node:test')
const assert = require('node:assert/strict')
const { countedText, check } = require('./check.js')

test('countedText: drops attribution, comments and footers', () => {
  const body = [
    '<!-- claude-projects-attribution: {"github_login":"x"} -->',
    '_Requested by **x** · [project thread](https://claude.ai/x)_',
    '',
    '## Summary',
    '- Does a thing.',
    '',
    '🤖 Generated with [Claude Code](https://claude.com/claude-code)',
    '',
    'https://claude.ai/code/session_123',
    '---',
    '_Generated by [Claude Code](https://claude.ai/code)_',
    '<!-- codesmith:footer -->',
    '<a href="x">Autofix</a>',
    '<!-- /codesmith:footer -->'
  ].join('\r\n')
  assert.equal(countedText(body), '## Summary\n- Does a thing.')
})

test('countedText: skips Decisions, Precedent and Reviewer notes at any level, with their subsections', () => {
  const body = '## Summary\nkept\n## Decisions:\n### Open question\ndropped\n## Notes\nkept too\n### Reviewer Notes (optional)\ndropped\n## Precedent\n| a | b |'
  assert.equal(countedText(body), '## Summary\nkept\n## Notes\nkept too')
})

test('countedText: ignores headings inside code fences', () => {
  const body = '## Summary\n````\n## Decisions\n~~~\n```\n````\nkept\n## Decisions\ndropped'
  assert.equal(countedText(body), '## Summary\n````\n## Decisions\n~~~\n```\n````\nkept')
})

test('countedText: inline code with backticks does not open a fence', () => {
  assert.equal(countedText('```npm ci```\n## Decisions\ndropped'), '```npm ci```')
})

test('countedText: a skipped subsection ends at a shallower counted heading', () => {
  assert.equal(countedText('### Reviewer notes\ndropped\n## Testing\nkept'), '## Testing\nkept')
})

test('countedText: handles a missing body', () => {
  assert.equal(countedText(null), '')
})

function run (body, { fetchFails = false, status = 404 } = {}) {
  const out = { info: [], warning: [], failed: [] }
  const core = {
    info: (m) => out.info.push(m),
    warning: (m) => out.warning.push(m),
    setFailed: (m) => out.failed.push(m)
  }
  const github = {
    rest: {
      pulls: {
        get: async () => {
          if (fetchFails) throw Object.assign(new Error('failed'), { status })
          return { data: { body } }
        }
      }
    }
  }
  const context = { repo: { owner: 'o', repo: 'r' }, payload: { pull_request: { number: 1, body: fetchFails ? body : 'stale' } } }
  return check({ github, context, core, limit: 10 }).then(() => out)
}

test('check: passes at the limit and fails over it, using the live body', async () => {
  assert.deepEqual((await run('x'.repeat(10))).failed, [])
  const out = await run('x'.repeat(11))
  assert.match(out.failed[0], /11 characters.*limit is 10.*re-run this job/)
})

test('check: counts characters, not UTF-16 units', async () => {
  assert.deepEqual((await run('🤖'.repeat(10))).failed, [])
})

test('check: falls back to the event body and says to push', async () => {
  const out = await run('x'.repeat(11), { fetchFails: true })
  assert.match(out.warning[0], /Grant pull-requests: read/)
  assert.match(out.failed[0], /push a commit to re-check/)
})

test('check: skips Mikado reference PRs', async () => {
  const out = await run('<!-- a -->\n> **Reference PR — do not merge.**\n' + 'x'.repeat(50))
  assert.deepEqual(out.failed, [])
})

test('check: only suggests the permission when access is denied', async () => {
  const out = await run('x', { fetchFails: true, status: 502 })
  assert.doesNotMatch(out.warning[0], /Grant/)
})
